import{z as i,x as A,o as e,c as s,q as B,j as t,D as a,d as o,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"复现包与配方管理","description":"","frontmatter":{"title":"复现包与配方管理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-repro-recipe-mgmt.md","filePath":"llm/pf2-repro-recipe-mgmt.md","lastUpdated":1791413859000}'),p={name:"llm/pf2-repro-recipe-mgmt.md"};function m(d,E,C,D,c,h){const r=A("Mermaid");return e(),s("div",null,[E[2]||(E[2]=B('<h1 id="复现包与配方管理" tabindex="-1">复现包与配方管理 <a class="header-anchor" href="#复现包与配方管理" aria-label="Permalink to &quot;复现包与配方管理&quot;">​</a></h1><div class="epigraph"><p>复现的单位不是模型权重，而是配方加指纹：权重是配方的最大那个派生物，派生物丢了源头就丢了。</p><footer>—— 据大规模训练配置管理与实验跟踪实践整理</footer></div><p><a href="/llm/pf2-opensource-recipes">上一课</a>用披露档位读别人的配方；本课反向操作：把自己的配方做成可对账、可复现、可交接的交付物。<a href="/llm/ti-recipe-management">配方六组字段</a>与<a href="/llm/ti-experiment-tracking">实验跟踪的四元组</a>在设施课已定；本课把它们与全课程十六个决策收进一个复现包，写成配方的存档形态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>训练结束时的知识状态最脆弱：配方散在配置文件、改动记录与几个人的记忆里；三个月后要回答「这个模型的数学能力是哪次改动带来的」，答案无处可寻。两种常见病：一种是<strong>快照病</strong>——只存了最终权重与一份 README，配方不可追溯，任何复现尝试都从猜开始；另一种是<strong>流水账病</strong>——什么改动都记，但没有结构，后来者在几千条 commit 里找不到主线。复现包的目标是让「模型—配置—结果」的双向谱系十分钟走通——设施课的验收标准在课程末尾兑现。</p><p><span class="marginnote">「身份四元组」就是给每次运行发的身份证：配置哈希（用了哪套配方）、代码版本（哪一行逻辑）、数据指纹（吃了哪些 token）、随机种子（掷了哪些骰子）。四样全对上，两次运行才谈得上是「同一次实验」。</span></p><h3 id="复现包的构成" tabindex="-1">复现包的构成 <a class="header-anchor" href="#复现包的构成" aria-label="Permalink to &quot;复现包的构成&quot;">​</a></h3><p>复现包五件。<strong>配方主文件</strong>：六组字段——模型、数据、优化、数值、观测、治理——每组是指针的集合：数据指向指纹与桶台账，优化指向超参迁移声明，观测指向绊网配置与死线，见<a href="/llm/ti-recipe-management">配方管理</a>。<strong>身份四元组</strong>：配置哈希、代码版本、数据指纹、种子，全链路同值。<strong>决策日志</strong>：本课程每个决策点的判据与结果——配比定稿的证据链、超参扫描的响应面、尖峰处置的死因判据、选点的拒绝记录。<strong>检查点指针</strong>：分线目录与谱系，指向权威快照而不拷贝副本。<strong>对外口径</strong>：评估门禁的分数表、边界声明与披露档位自评——按上一课的对照表给自己打分。</p>',8)),(e(),t(l,null,{default:a(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E9%85%8D%E6%96%B9%E4%B8%BB%E6%96%87%E4%BB%B6%EF%BC%9A%E5%85%AD%E7%BB%84%E5%AD%97%E6%AE%B5%E6%8C%87%E9%92%88%22%5D%20--%3E%20PACK%5B%22%E5%A4%8D%E7%8E%B0%E5%8C%85%22%5D%0A%20%20B%5B%22%E8%BA%AB%E4%BB%BD%E5%9B%9B%E5%85%83%E7%BB%84%EF%BC%9A%E5%93%88%E5%B8%8C%20%2F%20%E4%BB%A3%E7%A0%81%20%2F%20%E6%8C%87%E7%BA%B9%20%2F%20%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20PACK%0A%20%20C%5B%22%E5%86%B3%E7%AD%96%E6%97%A5%E5%BF%97%EF%BC%9A%E5%88%A4%E6%8D%AE%20%2B%20%E7%BB%93%E6%9E%9C%20%2B%20%E6%AD%BB%E5%9B%A0%22%5D%20--%3E%20PACK%0A%20%20D%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E6%8C%87%E9%92%88%EF%BC%9A%E5%88%86%E7%BA%BF%E4%B8%8E%E8%B0%B1%E7%B3%BB%22%5D%20--%3E%20PACK%0A%20%20E%5B%22%E5%AF%B9%E5%A4%96%E5%8F%A3%E5%BE%84%EF%BC%9A%E5%88%86%E6%95%B0%20%2B%20%E8%BE%B9%E7%95%8C%20%2B%20%E6%8A%AB%E9%9C%B2%E8%87%AA%E8%AF%84%22%5D%20--%3E%20PACK%0A%20%20PACK%20--%3E%20V%7B%22%E5%8F%8C%E5%90%91%E8%B0%B1%E7%B3%BB%E5%8D%81%E5%88%86%E9%92%9F%E8%B5%B0%E9%80%9A%EF%BC%9F%22%7D%0A%20%20V%20--%3E%7C%E5%90%A6%7C%20PACK%0A%20%20V%20--%3E%7C%E6%98%AF%7C%20ARCH%5B%22%E5%BD%92%E6%A1%A3%E4%B8%8E%E5%8D%87%E7%89%88%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>管理三条。第一，<strong>改动即升版</strong>：任何字段变更升配方版本并写继承声明（父版本加 diff）；训练中途改配方在制度上禁止——中途变更走显式例外通道（数据耗尽的再配比、门禁触发的结构升级），事后在决策日志里可查。第二，<strong>评审分级</strong>：改学习率与改配比的风险不同，评审的严格度分级，但<strong>改了不评审</strong>不存在；判据变更（门禁线、死线）一律高级评审。第三，<strong>归档带负结果</strong>：失败的 run、放弃的配比、废掉的扫描与成功同等归档——负结果可检索才不让学费重交，这是<a href="/llm/ti-failed-exp-archive">失败实验归档</a>的纪律在配方层的落点。</p><p><span class="marginnote">配方主文件是「指针的集合」而不是副本的集合：数据、检查点、评测产物都存指针，权威在各自的一级目录。副本式配方必然分叉——两处副本更新不同步的那天，就是「配置哈希三处不一」事故的开始。</span></p><p><span class="marginnote">直觉类比：航海日志只记抵达的航线，后来者就会把每片暗礁再撞一遍；把「这里试过、船怎么沉的」也写进日志，沉过的暗礁才真正从地图上消失。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么复现的单位是配方加指纹：权重的信息量来自整条决策链——数据怎么洗、配比怎么定、超参怎么迁、日程怎么签；权重本身不携带这条链。指纹（哈希、版本、种子、数据指纹）是链上每个环节的锚点，配方是链的显式化；两者合起来，复现才从「重跑碰运气」变成「按图施工」。为什么负结果必须进包：下一次配比决策的证据链里，「这个方向试过、死因是什么」与「成了」是同等信息；只归档成功的复现包会系统性高估当初的把握度。为什么十分钟验收：走不通的谱系等于没有谱系——超时的知识检索会被跳过，跳过一次就是失传的开始。</p><p><span class="marginnote">常见误区：初学者以为复现就是「拿到权重重新跑一遍推理」。真正的复现是从数据清洗到选点的整条决策链可重放；权重只是链的终点，链丢了，同款模型再也算不出来。</span></p>',7)),(e(),t(l,null,{default:a(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22%E5%8F%AA%E6%9C%89%E6%9D%83%E9%87%8D%EF%BC%9A%E5%BF%AB%E7%85%A7%E7%97%85%22%5D%20--%3E%20W1%5B%22%E5%A4%8D%E7%8E%B0%20%3D%20%E4%BB%8E%E7%8C%9C%E5%BC%80%E5%A7%8B%22%5D%0A%20%20L%5B%22%E4%BB%80%E4%B9%88%E9%83%BD%E8%AE%B0%EF%BC%9A%E6%B5%81%E6%B0%B4%E8%B4%A6%E7%97%85%22%5D%20--%3E%20L1%5B%22%E5%A4%8D%E7%8E%B0%20%3D%20%E5%9C%A8%E5%87%A0%E5%8D%83%E6%9D%A1%20commit%20%E9%87%8C%E6%89%BE%E4%B8%BB%E7%BA%BF%22%5D%0A%20%20S%5B%22%E9%85%8D%E6%96%B9%EF%BC%88%E9%93%BE%E7%9A%84%E6%98%BE%E5%BC%8F%E5%8C%96%EF%BC%89%2B%20%E6%8C%87%E7%BA%B9%EF%BC%88%E9%93%BE%E7%9A%84%E9%94%9A%E7%82%B9%EF%BC%89%22%5D%20--%3E%20S1%5B%22%E5%A4%8D%E7%8E%B0%20%3D%20%E6%8C%89%E5%9B%BE%E6%96%BD%E5%B7%A5%22%5D%0A%20%20W1%20--%3E%20V%7B%22%E5%8F%8C%E5%90%91%E8%B0%B1%E7%B3%BB%E5%8D%81%E5%88%86%E9%92%9F%E8%B5%B0%E9%80%9A%EF%BC%9F%22%7D%0A%20%20L1%20--%3E%20V%0A%20%20S1%20--%3E%20V%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p>这张图回答的是「三种存档形态各把复现变成什么」：快照病从猜开始，流水账病淹没在噪声里，只有配方加指纹能通过十分钟验收。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写配方的存档与交接形态，不重讲跟踪库与台账的实现——那是<a href="/llm/ti-experiment-tracking">实验跟踪</a>与<a href="/llm/ti-recipe-management">配方管理</a>的口径；本课消费它们做成包。对外发布的写作规范在<a href="/llm/eco-repro-report-writing">复现报告的写作</a>；本课交付的对外口径是它的原料。权限与合规（数据许可、敏感样本）是数据工程与合规课的事，复现包只挂指针。最后，复现包不是博物馆：每次点火后都要更新——配方是活的文档，本课程也把「管理」交还给下一次开工。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复现包五件：配方主文件（六组指针）、身份四元组、决策日志、检查点指针、对外口径。</li><li>配方是指针的集合，不做副本；副本分叉即指纹事故。</li><li>改动即升版加继承声明；中途改配方只走显式例外通道。</li><li>负结果与成功同等归档；双向谱系十分钟走通是验收线。</li><li>出处：据大规模训练配置管理、实验跟踪与复现实践整理；对照 OLMo 2 的公开配方结构（arXiv:2501.00656）。</li></ul>',5))])}const f=i(p,[["render",m]]);export{_ as __pageData,f as default};
